function sameSubnet(a, b, mask) {
  var x = a.split('.'), y = b.split('.'), m = mask.split('.');
  for (var i = 0; i < 4; i++) if ((Number(x[i]) & Number(m[i])) !== (Number(y[i]) & Number(m[i]))) return false;
  return true;
}

